/* From Uiverse.io by Cevorob - Tags: hamburger */
.__UIV_SCOPE__ .burger {
  position: relative;
  width: 40px;
  height: 30px;
  background: transparent;
  cursor: pointer;
  display: block;
}

.__UIV_SCOPE__ .burger input {
  display: none;
}

.__UIV_SCOPE__ .burger span {
  display: block;
  position: absolute;
  height: 4px;
  width: 100%;
  background: black;
  border-radius: 9px;
  opacity: 1;
  left: 0;
  transform: rotate(0deg);
  transition: .25s ease-in-out;
}

.__UIV_SCOPE__ .burger span:nth-of-type(1) {
  top: 0px;
  transform-origin: left center;
}

.__UIV_SCOPE__ .burger span:nth-of-type(2) {
  top: 50%;
  transform: translateY(-50%);
  transform-origin: left center;
}

.__UIV_SCOPE__ .burger span:nth-of-type(3) {
  top: 100%;
  transform-origin: left center;
  transform: translateY(-100%);
}

.__UIV_SCOPE__ .burger input:checked ~ span:nth-of-type(1) {
  transform: rotate(45deg);
  top: 0px;
  left: 5px;
}

.__UIV_SCOPE__ .burger input:checked ~ span:nth-of-type(2) {
  width: 0%;
  opacity: 0;
}

.__UIV_SCOPE__ .burger input:checked ~ span:nth-of-type(3) {
  transform: rotate(-45deg);
  top: 28px;
  left: 5px;
}
